class FfiConverterTypeUiHost: FfiConverter<UiHost, ulong> {
    public ConcurrentHandleMap<UiHost> handleMap = new ConcurrentHandleMap<UiHost>();
    
    public static FfiConverterTypeUiHost INSTANCE = new FfiConverterTypeUiHost();

    static FfiConverterTypeUiHost() {
        UniffiCallbackInterfaceUiHost.Register();
    }

    public override ulong Lower(UiHost value) {
        if (value is UiHostImpl rustObj) {
            // Rust-implemented object. Clone the handle and return it.
            return rustObj.CallWithPointer(thisPtr => thisPtr);
        } else {
            // C# object, generate a new handle map entry and return it.
            return handleMap.Insert(value);
        }
    }

    public override UiHost Lift(ulong value) {
        if ((value & 1UL) == 0UL) {
            // Rust-generated handle, construct a new wrapper.
            return new UiHostImpl(value);
        } else {
            // C#-generated handle, retrieve and remove from the handle map.
            if (handleMap.Remove(value, out var obj)) {
                return obj;
            } else {
                throw new InternalException($"No callback in handlemap '{value}'");
            }
        }
    }

    public override UiHost Read(BigEndianStream stream) {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(UiHost value) {
        return 8;
    }

    public override void Write(UiHost value, BigEndianStream stream) {
        stream.WriteULong(Lower(value));
    }
}



