/// <summary>
/// Why the core could not start.
/// </summary>
public class StartException: UniffiException {
    StartException() : base() {}
    StartException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// [`Core::start`] was called twice.
    /// </summary>
    public class AlreadyStarted : StartException {
        public AlreadyStarted() : base() {}
    }
    
    
    /// <summary>
    /// [`Core::start`] was called after [`Core::shutdown`].
    /// </summary>
    public class ShutDown : StartException {
        public ShutDown() : base() {}
    }
    
    
    /// <summary>
    /// Something the core runs on could not be set up.
    /// </summary>
    
    public class Setup : StartException {
        // Members
        public string @detail;

        // Constructor
        public Setup(
                string @detail) : base(
                "@detail" + "=" + @detail) {

            this.@detail = @detail;
        }
    }
    

    
}

class FfiConverterTypeStartError : FfiConverterRustBuffer<StartException>, CallStatusErrorHandler<StartException> {
    public static FfiConverterTypeStartError INSTANCE = new FfiConverterTypeStartError();

    public override StartException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new StartException.AlreadyStarted();
            case 2:
                return new StartException.ShutDown();
            case 3:
                return new StartException.Setup(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeStartError.Read()", value));
        }
    }

    public override int AllocationSize(StartException value) {
        switch (value) {

            case StartException.AlreadyStarted variant_value:
                return 4;

            case StartException.ShutDown variant_value:
                return 4;

            case StartException.Setup variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeStartError.AllocationSize()", value));
        }
    }

    public override void Write(StartException value, BigEndianStream stream) {
        switch (value) {
            case StartException.AlreadyStarted variant_value:
                stream.WriteInt(1);
                break;
            case StartException.ShutDown variant_value:
                stream.WriteInt(2);
                break;
            case StartException.Setup variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeStartError.Write()", value));
        }
    }
}





/// <summary>
